  "status": "SUPPORTED",
  "claim": {
    "component_id": "C033.component",
    "value": "Meeting the predeclared benefit criteria is necessary for rollout.",
    "scope": "This is one rollout gate, not a sufficient condition by itself; the predeclared guardrail criteria must also be met.",
    "provenance": {
      "refs": [
        {
          "source_id": "P021",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The explicit rollout rule makes benefit and guardrail criteria jointly necessary."
    }
  },
  "signal_basis": {
    "component_id": "C033.signal_basis",
    "value": "The release comparison measures first-publication rates, publication timing, retention at the targeted checkpoint and predefined guardrails; results are assessed against predeclared benefit and guardrail criteria.",
    "scope": "The selected release comparison, with publication rates measured within a common window and evidence and worthwhile-improvement thresholds set before reviewing results.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the thresholds, observed outcomes and rule connecting their assessment to rollout."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C033.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this explicit decision rule."
    }
  },
  "rationale": "The claim follows directly from the mapping's only-if rollout rule. Its necessity is procedural within this plan, and satisfying benefit criteria alone does not authorize rollout.",
  "uncertainty": "Whether the observed results actually meet the criteria is unspecified; that does not affect their status as a necessary rollout gate.",
  "anomalies": []
}
